import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:highlight_creator/data/l10n.dart';
import 'package:highlight_creator/data/settings_service.dart';

/// Beginner guide dialog: 8 swipeable pages with annotated screenshots.
///
/// The page images live in `windows/res/` (bundled as assets) and are
/// generated by `test/e2e/guide_screenshots_test.dart`.
class GuideDialog extends ConsumerStatefulWidget {
  const GuideDialog({super.key});

  @override
  ConsumerState<GuideDialog> createState() => _GuideDialogState();
}

class _GuideDialogState extends ConsumerState<GuideDialog> {
  static const int pageCount = 8;

  final PageController _pageController = PageController();
  int _page = 0;
  bool _dontShowAgain = false;

  @override
  void initState() {
    super.initState();
    _loadDontShowAgain();
  }

  Future<void> _loadDontShowAgain() async {
    final autoShow = await ref.read(settingsServiceProvider).guideAutoShow;
    if (mounted) setState(() => _dontShowAgain = !autoShow);
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  String _assetPath(int index, String lang) {
    final code = lang == '中文' ? 'zh' : 'en';
    final n = (index + 1).toString().padLeft(2, '0');
    return 'windows/res/guide_${code}_$n.png';
  }

  List<String> _captions(AppStrings l10n) => [
        l10n.guideStep1,
        l10n.guideStep2,
        l10n.guideStep3,
        l10n.guideStep4,
        l10n.guideStep5,
        l10n.guideStep6,
        l10n.guideStep7,
        l10n.guideStep8,
      ];

  void _goTo(int page) {
    _pageController.animateToPage(
      page,
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(l10nProvider);
    final lang = ref.watch(languageProvider);
    final theme = Theme.of(context);
    final captions = _captions(l10n);
    final isLast = _page == pageCount - 1;

    return Dialog(
      key: const Key('guide_dialog'),
      backgroundColor: theme.colorScheme.surfaceContainer,
      insetPadding: const EdgeInsets.all(24),
      child: SizedBox(
        width: 960,
        height: 620,
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 8, 8, 8),
              child: Row(
                children: [
                  Icon(Icons.menu_book, color: theme.colorScheme.primary),
                  const SizedBox(width: 8),
                  Text(l10n.guideTitle,
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w600)),
                  const Spacer(),
                  Text('${_page + 1} / $pageCount',
                      style: TextStyle(
                          fontSize: 12,
                          color: theme.colorScheme.outline)),
                  const SizedBox(width: 8),
                  IconButton(
                    icon: const Icon(Icons.close, size: 18),
                    onPressed: () => Navigator.of(context).pop(),
                  ),
                ],
              ),
            ),
            const Divider(height: 1),
            Expanded(
              child: PageView.builder(
                controller: _pageController,
                itemCount: pageCount,
                onPageChanged: (i) => setState(() => _page = i),
                itemBuilder: (context, i) => Column(
                  children: [
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(24, 16, 24, 8),
                        child: Image.asset(
                          _assetPath(i, lang),
                          fit: BoxFit.contain,
                          errorBuilder: (_, __, ___) => Center(
                            child: Text('${i + 1}',
                                style: theme.textTheme.displaySmall),
                          ),
                        ),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.fromLTRB(32, 0, 32, 8),
                      child: Text(captions[i],
                          textAlign: TextAlign.center,
                          style: theme.textTheme.bodyLarge),
                    ),
                  ],
                ),
              ),
            ),
            const Divider(height: 1),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
              child: Row(
                children: [
                  SizedBox(
                    width: 280,
                    child: CheckboxListTile(
                      key: const Key('guide_checkbox'),
                      dense: true,
                      controlAffinity: ListTileControlAffinity.leading,
                      contentPadding: EdgeInsets.zero,
                      title: Text(l10n.guideDontShowAgain,
                          style: const TextStyle(fontSize: 12)),
                      value: _dontShowAgain,
                      onChanged: (v) {
                        setState(() => _dontShowAgain = v ?? false);
                        ref
                            .read(settingsServiceProvider)
                            .setGuideAutoShow(!(v ?? false));
                      },
                    ),
                  ),
                  Expanded(
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        for (var i = 0; i < pageCount; i++)
                          Container(
                            margin: const EdgeInsets.symmetric(horizontal: 3),
                            width: 8,
                            height: 8,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: i == _page
                                  ? theme.colorScheme.primary
                                  : theme.colorScheme.outline.withAlpha(80),
                            ),
                          ),
                      ],
                    ),
                  ),
                  TextButton(
                    key: const Key('guide_prev'),
                    onPressed: _page > 0 ? () => _goTo(_page - 1) : null,
                    child: Text(l10n.guidePrev),
                  ),
                  const SizedBox(width: 8),
                  FilledButton(
                    key: const Key('guide_next'),
                    onPressed:
                        isLast ? () => Navigator.of(context).pop() : () => _goTo(_page + 1),
                    child: Text(isLast ? l10n.guideDone : l10n.guideNext),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
